learn=[('Follow the actual export path', 'The Agent SDK launches an instrumented CLI. Response messages return through the SDK pipe; OTLP data travels separately to the receiver.'), ('Select three independent signals', 'Enable telemetry, then choose metrics, log events and beta traces independently. Compare all signals with metrics-only, logs-only and traces-only experiments.'), ('Read a native trace tree', 'Inspect interaction, model-request and Read-tool spans, their durations, parent IDs and trace IDs. The diagram labels host code separately from CLI instrumentation.'), ('Link an application span', 'Run query() inside a real active OpenTelemetry host span. Verify the CLI interaction shares its trace ID and references its span ID.'), ('Tag and filter classroom activity', 'Set service.name and encoded resource attributes. Filter actual tool-result events by the fictional enduser.id, without exposing account identity.'), ('Verify delivery and control content', 'Compare default telemetry with explicit synthetic prompt/tool-content logging. Observe a deliberately rejected endpoint and an agent that still finishes. Short export intervals help short calls but cannot guarantee delivery.')]
labels=[('all', 'All three signals · native export'), ('metrics', 'Metrics only · token and cost series'), ('logs', 'Log events only · native activity'), ('traces', 'Beta traces only · span tree'), ('linked', 'Active host span · one linked trace'), ('tags', 'Classroom user tags · filter events'), ('content', 'Synthetic content opt-in · compare defaults'), ('off', 'Telemetry disabled · normal response'), ('unreachable', 'Rejected endpoint · diagnose export failure')]
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. Windows may require Git Bash. The app starts a loopback OTLP HTTP/JSON receiver on a free port per run; no Docker or hosted observability account is needed.', 'node --version\nnpm --version'), ('Install and configure', 'Preserve an existing .env, or copy the template. Enter your model API key privately. The local receiver uses generated authentication; no collector token is required in .env.', 'cd .\\agent-sdk\\lesson47-opentelemetry\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open. Visit all five pages. Use the experiment selector, native trace tree, metric points, event filter, diagnostics and downloadable evidence.', 'npm start\n# http://127.0.0.1:3147'), ('Compare the three signals', 'Run All, Metrics, Logs and Traces separately. The UI displays exactly what arrived. Metrics may export several delta batches: rows are points, not unique metric names or a session total.', 'npm run sample:env -- all\nnpm run sample:env -- metrics\nnpm run sample:env -- logs\nnpm run sample:env -- traces'), ('Link and attribute', 'Linked creates an actual active host span and exports it through the official OTLP exporter. Tags attaches the fictional student 47 identity. Filter the event table by that exact value.', 'npm run sample:env -- linked\nnpm run sample:env -- tags'), ('Inspect content and failure', 'Content opts in only for disposable fictional notes. Off disables CLI export. Rejected endpoint returns a real HTTP 503: compare successful SDK completion with receiver rejection records and stderr diagnostics.', 'npm run sample:env -- content\nnpm run sample:env -- off\nnpm run sample:env -- unreachable\nnpm test')]
specs=[('Validate the selected experiment', 'src/protocol.ts', 'if (', 'Accept a fixed experiment only. Browser input cannot choose an arbitrary telemetry destination or add tools.', 0, 1, 7), ('Start the local OTLP receiver', 'src/collector.ts', 'server.listen(0,', 'Bind a private loopback port chosen by the OS. The classroom receiver keeps bounded per-run data in memory; it is not a production Collector distribution.', 1, 3, 5), ('Enable the selected signals', 'src/settings.ts', 'CLAUDE_CODE_ENABLE_TELEMETRY:', 'Select OTLP exporters for each signal and enable beta tracing where needed. Off explicitly disables telemetry.', 1, 2, 5), ('Configure OTLP and short intervals', 'src/settings.ts', 'OTEL_EXPORTER_OTLP_PROTOCOL:', 'Use standard OTLP HTTP/JSON for inspectable native exports. The lesson slide uses HTTP/protobuf, another supported encoding. One-second intervals reduce short-run batching windows.', 1, 2, 6), ('Preserve the private process environment', 'src/agent.ts', 'env: {', 'Preserve PATH and private credentials while replacing inherited exporter routing with this per-run local configuration. Isolate SDK state in the disposable workspace.', 1, 2, 4), ('Create an active application span', 'src/tracing.ts', 'return trace', 'Linked mode enters an actual active OpenTelemetry span before query(). The SDK automatically injects its W3C context into the CLI.', 1, 2, 7), ('Run query and consume native messages', 'src/agent.ts', 'for await (const message of query', 'The regular SDK response stream stays separate from OTLP exports. Only the disposable Read task is available.', 1, 2, 5), ('Receive and decode native OTLP', 'src/collector.ts', 'const payload = sanitize', 'Parse actual JSON batches received over HTTP, sanitize account identity, then flatten each signal without inventing spans or metrics.', 2, 3, 5), ('Retain span IDs and resource tags', 'src/collector.ts', 'if (signal === "traces")', 'Preserve native parent links and resource attributes. The browser derives its tree from those IDs. Hook spans require separate detailed beta tracing, which this app does not enable.', 3, 4, 10), ('Export the finished host span', 'src/tracing.ts', 'const exporter = new OTLPTraceExporter', 'Export the real host span through the official OpenTelemetry exporter to the same receiver. Verify matching trace and parent IDs in Linked mode.', 1, 3, 4), ('Attach encoded classroom attributes', 'src/settings.ts', 'const user = mode ===', 'Use a fictional classroom identity and percent-encode its space in OTEL_RESOURCE_ATTRIBUTES. The decoded enduser.id can filter tool-result events.', 1, 2, 3), ('Make content logging explicit', 'src/settings.ts', 'OTEL_LOG_USER_PROMPTS:', 'Content mode opts in to synthetic prompt, tool details and tool output. Raw API bodies remain disabled. Default structural telemetry can still contain identifiers; the receiver sanitizes account attributes.', 1, 2, 5), ('Compare delivery with agent completion', 'src/agent.ts', 'const data = receiver.snapshot();', 'Keep receiver requests, diagnostics and SDK results as independent evidence. A successful agent response does not prove telemetry was accepted; the rejected-endpoint mode demonstrates this.', 3, 4, 6)]
reference=[('Classroom receiver versus production collector', 'The included receiver accepts actual OTLP HTTP/JSON exports into memory and closes after each run. It does not provide durable storage, retries, a production collector pipeline or a hosted tracing service. Use an OpenTelemetry Collector and your chosen backend for production.'), ('Traces are beta', 'The pinned runtime currently emits interaction, llm_request and tool spans. Span names and attributes may change. Native hook spans require additional detailed beta tracing settings and an endpoint override; the normal PreToolUse callback is not presented as a hook span.'), ('The response channel stays separate', 'Do not use the console exporter through the SDK, because it writes into the SDK message channel. This sample receives native telemetry over a separate HTTP endpoint.'), ('Trace context is actual', 'Linked mode uses a registered NodeTracerProvider, an active span and the official HTTP trace exporter. No trace IDs or parent IDs are fabricated. Only this experiment creates a host span; the other trace experiments show CLI roots.'), ('Metrics are points, not a bill', 'The table shows raw native metric points, attributes and aggregation temporality. Repeated exports are not automatically summed. Native cost metrics are estimates, not an invoice. The app does not query organization billing.'), ('Privacy and opt-in content', 'Only a fictional disposable note is available to Read. Content logging is off by default and enabled only in the labelled Content experiment. Even structural telemetry can carry session or user identifiers. The classroom receiver redacts account user/organization attributes and the current API credential before UI storage. This is not a comprehensive production DLP solution.'), ('Diagnose failure', 'Rejected endpoint uses a live authenticated receiver path returning HTTP 503. It records rejections, accepts no telemetry for that path, and captures exporter diagnostics through the SDK stderr option. This is a deliberate HTTP rejection rather than an invented network outage.'), ('Short-lived exporters', 'One-second metrics, log and trace intervals help exports arrive while the task is running. Clean process shutdown tries to flush but cannot guarantee delivery, and killed processes can lose buffered data.'), ('Per-user filtering', 'Tags uses enduser.id=student%2047 and tenant.id=demo-school. The native resource contains the decoded value student 47. These are synthetic teaching identities, not the API account owner.'), ('Primary references', 'https://code.claude.com/docs/en/agent-sdk/observability · https://code.claude.com/docs/en/monitoring-usage · https://opentelemetry.io/docs/languages/js/exporters/')]
body='<div class="flow"><div><b>01 · Configure</b><p>Select native signals</p></div><span>→</span><div><b>02 · Observe</b><p>Run the real SDK</p></div><span>→</span><div><b>03 · Verify</b><p>Inspect received OTLP</p></div></div><section class="panel" id="controls"><h2>See inside a real agent run</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Telemetry experiment</label><select id="mode"><option value="all">All three signals · native export</option><option value="metrics">Metrics only · token and cost series</option><option value="logs">Log events only · native activity</option><option value="traces">Beta traces only · span tree</option><option value="linked">Active host span · one linked trace</option><option value="tags">Classroom user tags · filter events</option><option value="content">Synthetic content opt-in · compare defaults</option><option value="off">Telemetry disabled · normal response</option><option value="unreachable">Rejected endpoint · diagnose export failure</option></select><button class="primary" id="run" disabled>Run telemetry experiment →</button><p>One disposable note, Read only, four-turn limit and $0.30 SDK estimate threshold. Each run starts its own authenticated local receiver and removes its temporary SDK workspace afterward.</p></section><section class="step" id="specialists-panel"><h2>Actual OTLP received</h2><div class="grid"><article class="card"><h3>Spans</h3><p class="metric" id="span-count">0</p></article><article class="card"><h3>Metric points</h3><p class="metric" id="metric-count">0</p></article><article class="card"><h3>Log records</h3><p class="metric" id="log-count">0</p></article></div><p>Counts show received native records. Export batches can repeat metric names; these are not billing totals. No telemetry records are synthesized.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Actual SDK telemetry configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div><section class="step" id="trace-panel"><h2>Native trace tree</h2><p>Parent links come from received native IDs. A CLI parent not received in this batch is shown as a root. Linked mode also exports the real classroom.http.request host span.</p><div class="table"><table><thead><tr><th>Span</th><th>Trace ID</th><th>Span ID</th><th>Parent ID</th><th>Duration ms</th></tr></thead><tbody id="trace-history"></tbody></table></div></section><section class="step" id="metric-panel"><h2>Native metric points</h2><p>Read the aggregation temporality before accumulating metric points. This table preserves received points without inventing a total.</p><div class="table"><table><thead><tr><th>Metric</th><th>Value</th><th>Unit</th><th>Attributes</th><th>Temporality</th></tr></thead><tbody id="metric-history"></tbody></table></div></section><section class="step" id="model-panel"><h2>Native log events and classroom user filter</h2><label for="user-filter">Filter by exact enduser.id</label><input id="user-filter" placeholder="student 47"><p>Leave blank for all events. Tags exports the fictional identity student 47.</p><div class="table"><table><thead><tr><th>Event</th><th>enduser.id</th><th>Trace ID</th><th>Attributes</th></tr></thead><tbody id="log-history"></tbody></table></div></section><section class="step" id="results-panel"><h2>Native SDK result</h2><pre class="json-view"><code class="language-json" id="native-result">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Receiver delivery and rejection records</h2><pre class="json-view"><code class="language-json" id="requests">{}</code></pre></section><section class="step" id="storage-panel"><h2>Trace linkage and content-presence checks</h2><pre class="json-view"><code class="language-json" id="storage">{}</code></pre></section><section class="step" id="diagnostic-panel"><h2>Native exporter stderr diagnostics</h2><pre class="json-view"><code class="language-json" id="diagnostics">{}</code></pre></section><section class="step" id="observation-panel"><h2>All received telemetry · sanitized</h2><pre class="json-view"><code class="language-json" id="telemetry">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent actual run evidence</h2><pre class="json-view"><code class="language-json" id="evidence">{}</code></pre><button id="download">Download actual observations</button></section>'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3147\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'

document('/','Observe your agent. <em>Follow every signal.</em>','Inspect actual CLI traces, metrics and events in a local classroom telemetry viewer.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Configure, link, tag and verify native telemetry.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your private .env</h2>'+snippet(env,'dotenv')+'<p>Keep the key private, restart after edits, and preserve an existing file. Existing shell values take precedence. If the port is occupied, change PORT.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install, configure privately and inspect the nine experiments.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','CLI runtime','OTLP receiver','Web viewer']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='javascript' if source.endswith('.js') else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 47 · Configure → run → receive → inspect</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The host starts a per-run OTLP receiver. CLI response messages return through the SDK; telemetry travels separately over HTTP. Receiver and viewer are classroom components, not a production collector backend. Some numbered steps describe alternative experiments.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked observability workflow steps"></div>'+walk)

document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has matching coloured TypeScript.',cards(reference)+walk)

readme='# Claude Agent SDK · Lesson 47 · Observability with OpenTelemetry\n\nFive student pages, a native OTLP viewer and thirteen source-linked UML code steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson47-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson47-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations: `cd .\\agent-sdk\\lesson47-opentelemetry`. Open http://127.0.0.1:3147. Node 24+, API credit and Windows Git Bash if needed.\n\n## Create your .env file\n\nCopy the template once and enter your own model key privately. Restart after edits. Existing shell values take precedence.\n\n```dotenv\n'+env+'```\n\nLocal receiver authentication is generated per run. No hosted collector token, GitHub token or Managed Agents IDs are needed.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for s in steps:readme+=f'### {s["number"]}. {s["title"]}\n\n{s["explanation"]}\n\nSource: `{s["source"]}`, selected lines {s["firstLine"]}–{s["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{s["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## Validation\n\nRun `npm test` and `npm run build:client`. Regenerate pages with `python scripts/build-pages.py`. Secrets, dependencies, recordings and teaching media are excluded from Git.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
(PUBLIC/'style.css').write_text((PUBLIC/'style.css').read_text(encoding='utf-8')+'\n.metric{font-size:34px;font-weight:800}.json-view{max-height:380px}.table{max-height:420px;overflow:auto}td{min-width:140px;max-width:500px;overflow-wrap:anywhere}.markdown-body{font-size:22px;line-height:1.65}#conversation{max-height:450px;overflow:auto}input{width:100%;font:inherit;padding:16px;border:1px solid var(--line);border-radius:14px;color:var(--ink);background:var(--paper)}\n',encoding='utf-8')
print('Built five Lesson 47 pages with 13 coloured workflow snippets.')
